entries[17951] = { ["name"] = "Feuerstein herstellen", ["text"] = "700 Mana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nStellt einen Feuerstein her, der angelegt werden kann. Wenn angelegt, wird die Waffenhandwaffe mit Feuer verzaubert und gewährt jedem Angriff die Chance, 40 bis 60 zusätzlichen Feuerschaden zuzufügen. Außerdem erhöht das Anlegen eines Feuersteins den Schaden von Feuerzaubern um 14.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[17952] = { ["name"] = "Feuerstein herstellen", ["text"] = "900 Mana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nStellt einen großen Feuerstein her, der angelegt werden kann. Wenn angelegt, wird die Waffenhandwaffe mit Feuer verzaubert und gewährt jedem Angriff die Chance, 60 bis 90 zusätzlichen Feuerschaden zuzufügen. Außerdem erhöht das Anlegen eines Feuersteins den Schaden von Feuerzaubern um 17.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
