entries[18788] = { ["name"] = "Dämonische Opferung", ["text"] = "100 Meter Reichweite\nSofort\nBei Aktivierung wird Euer beschworener Dämon geopfert, um Euch einen Effekt zu gewähren, der 30 Min. lang anhält. Der Effekt wird abgebrochen, wenn ein Dämon beschworen wird.\n\nWichtel: Erhöht Euren Feuerschaden um 15%.\n\nLeerwandler: Stellt alle 4 Sek. 2% Eurer gesamten Gesundheit wieder her.\n\nSukkubus/Inkubus: Erhöht Euren Schattenschaden um 15%.\n\nTeufelsjäger: Stellt alle 4 Sek. 3% Eures gesamten Manas wieder her.\n\nTeufelswache: Erhöht Euren Schattenschaden um 10% und stellt alle 4 Sek. 2% Eures gesamten Manas wieder her." }
